import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"13、【同人】 離下乾上","description":"橫渠易說 - 13、【同人】 離下乾上","frontmatter":{"title":"13、【同人】 離下乾上","description":"橫渠易說 - 13、【同人】 離下乾上"},"headers":[],"relativePath":"classics/hengqu/015.md","filePath":"classics/hengqu/015.md"}'),l={name:"classics/hengqu/015.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_13、【同人】-離下乾上" tabindex="-1">13、【同人】 離下乾上 <a class="header-anchor" href="#_13、【同人】-離下乾上" aria-label="Permalink to “13、【同人】 離下乾上”">​</a></h1><h3 id="彖曰-同人-柔得位-得中而應乎乾曰同人。同人曰-同人於野亨-利涉大川-乾行也。文明以健-中正而應-君子正也。唯君子為能通天下之志。" tabindex="-1">彖曰：同人，柔得位，得中而應乎乾曰同人。同人曰“同人於野亨，利涉大川”，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。 <a class="header-anchor" href="#彖曰-同人-柔得位-得中而應乎乾曰同人。同人曰-同人於野亨-利涉大川-乾行也。文明以健-中正而應-君子正也。唯君子為能通天下之志。" aria-label="Permalink to “彖曰：同人，柔得位，得中而應乎乾曰同人。同人曰“同人於野亨，利涉大川”，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。”">​</a></h3><h3 id="象曰-天與火-同人-君子以類族辨物。" tabindex="-1">象曰：天與火，同人，君子以類族辨物。 <a class="header-anchor" href="#象曰-天與火-同人-君子以類族辨物。" aria-label="Permalink to “象曰：天與火，同人，君子以類族辨物。”">​</a></h3><p>不能與人同，未足為正也。 天下之心，天下之志，自是一物，天何常有如此間別!</p><h3 id="初九-同人於門-無咎。-象曰-出門同人-又誰咎也" tabindex="-1">初九，同人於門，無咎。 象曰：出門同人，又誰咎也! <a class="header-anchor" href="#初九-同人於門-無咎。-象曰-出門同人-又誰咎也" aria-label="Permalink to “初九，同人於門，無咎。 象曰：出門同人，又誰咎也!”">​</a></h3><h3 id="六二-同人於宗-吝。-象曰-同人於宗-吝道也。" tabindex="-1">六二，同人於宗，吝。 象曰：“同人於宗”，吝道也。 <a class="header-anchor" href="#六二-同人於宗-吝。-象曰-同人於宗-吝道也。" aria-label="Permalink to “六二，同人於宗，吝。 象曰：“同人於宗”，吝道也。”">​</a></h3><h3 id="九三-伏戎於莽-升其高陵-三歲不興。-象曰-伏戎於莽-敵剛也。-三歲不興-安行也。" tabindex="-1">九三，伏戎於莽，升其高陵，三歲不興。 象曰：“伏戎於莽”，敵剛也。“三歲不興”，安行也。 <a class="header-anchor" href="#九三-伏戎於莽-升其高陵-三歲不興。-象曰-伏戎於莽-敵剛也。-三歲不興-安行也。" aria-label="Permalink to “九三，伏戎於莽，升其高陵，三歲不興。 象曰：“伏戎於莽”，敵剛也。“三歲不興”，安行也。”">​</a></h3><h3 id="九四-乘其墉-弗克-攻-吉。-象曰-乘其墉-義弗克也。其吉則困而反則也。" tabindex="-1">九四，乘其墉，弗克，攻，吉。 象曰：“乘其墉”，義弗克也。其吉則困而反則也。 <a class="header-anchor" href="#九四-乘其墉-弗克-攻-吉。-象曰-乘其墉-義弗克也。其吉則困而反則也。" aria-label="Permalink to “九四，乘其墉，弗克，攻，吉。 象曰：“乘其墉”，義弗克也。其吉則困而反則也。”">​</a></h3><h3 id="九五-同人先號啕而後笑-大師克相遇。-象曰-同人之先-以中直也。大師相遇-言相剋也。" tabindex="-1">九五，同人先號啕而後笑，大師克相遇。 象曰：同人之先，以中直也。大師相遇，言相剋也。 <a class="header-anchor" href="#九五-同人先號啕而後笑-大師克相遇。-象曰-同人之先-以中直也。大師相遇-言相剋也。" aria-label="Permalink to “九五，同人先號啕而後笑，大師克相遇。 象曰：同人之先，以中直也。大師相遇，言相剋也。”">​</a></h3><h3 id="上九-同人於郊-無悔。-象曰-同人於郊-志未得也。" tabindex="-1">上九，同人於郊，無悔。 象曰：“同人於郊”，志未得也。 <a class="header-anchor" href="#上九-同人於郊-無悔。-象曰-同人於郊-志未得也。" aria-label="Permalink to “上九，同人於郊，無悔。 象曰：“同人於郊”，志未得也。”">​</a></h3><p>二與五應而為他間，己直人曲，望之必深，故號啕也。師直而壯，義同必克，故遇而後笑。</p>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
